import React, { useState, useEffect, useContext } from "react";
import "./ReportList.css"; // Import CSS for styling
import { useNavigate } from "react-router-dom";
import axiosInstance from "Services/AxiosInstane";
import { toast } from "react-toastify";
import Loading from "../../images/loading.png";
import { ToggleButton, ToggleButtonGroup } from "@mui/material";
import { Typography } from "@mui/material";
import { PoolContext } from "../../Context/PoolContext";
import { CircularProgress } from "@mui/material";

const ReportList = () => {
  const [reports, setReports] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedReport, setSelectedReport] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [alignment, setAlignment] = useState("Vamanit");
  const [deleteLoading, setDeleteLoading] = useState({});

  const handleChange = (event, newAlignment) => {
    if (newAlignment !== null && newAlignment !== alignment) {
      setAlignment(newAlignment);
      setCurrentPage(1);
    }
  };

  const itemsPerPage = 9;

  const totalPages = Math.ceil(reports.length / itemsPerPage);
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = reports.slice(indexOfFirstItem, indexOfLastItem);

  const paginate = (pageNumber) => setCurrentPage(pageNumber);

  const pc = useContext(PoolContext);
  const token = pc.token;

  useEffect(() => {
    const fetchReports = async () => {
      try {
        setIsLoading(true);
        // const response = await a.get(process.env.REACT_APP_FRONTEND_URL + `/get_schedules/`);
        // let url = await process.env.REACT_APP_FRONTEND_URL + `/get_schedules/`;
        // if (selectedReportType){
        //     url = await `${process.env.REACT_APP_FRONTEND_URL}/get_schedules_report/${selectedReportType}/`;
        //     console.log(selectedReportType);  // Make sure it's a string

        // }

        // const response = await a.get(url);
        // const response = await a.get(`${process.env.REACT_APP_FRONTEND_URL}/get_schedules_report/${alignment}`);
        const response = await axiosInstance.get(
          `${process.env.REACT_APP_BACKEND_URL}/v1/schedule/get_schedules_report/${alignment}`,
          {
            headers: {
              Authorization: `Bearer ${token}`, // Include the token in the headers
            },
          }
        );
       
        const reportsWithStatus = await Promise.all(
          response.data.items.map(async (report) => {
            const status = await fetchScheduleStatus(report.schedule_id);
            return { ...report, status };
          })
        );
       
        setReports(reportsWithStatus);
      } catch (error) {
        console.error("Error:", error);
        toast.error("Data Not Found. FOR FECH.");
      } finally {
        setIsLoading(false);
      }
    };
    fetchReports();
  }, [alignment]);

  const fetchScheduleStatus = async (reportId) => {
    try {
      // const response = await a.get(`${process.env.REACT_APP_FRONTEND_URL}/get_schedule_status/${reportId}`);
      const response = await axiosInstance.get(
        `${process.env.REACT_APP_BACKEND_URL}/v1/schedule/get_schedule_status/${reportId}`,
        {
          headers: {
            Authorization: `Bearer ${token}`, // Add the Authorization header with the token
          },
        }
      );
      if (response.data === "Docker Is Not Stared Yet") {
        return "Failed to get status";
      } else {
        console.log(response.data,);
        return response.data;
      }
    } catch (error) {
      
      toast.error("Data Not Found. Please try again later.");
    }
  };

  const handleDelete = async (id) => {
    setDeleteLoading((prev) => ({ ...prev, [id]: true }));
    if (window.confirm("Are you sure you want to delete")) {
      try {
        // const token = localStorage.getItem('token');
        await axiosInstance.delete(
          `${process.env.REACT_APP_BACKEND_URL}/v1/schedule/delete_schedule/${id}/`,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );
        setReports(reports.filter((report) => report.id !== id));
        if (currentItems.length === 1 && currentPage > 1) {
          setCurrentPage((prevPage) => prevPage - 1);
        }

        toast.success("Report deleted successfully");
        if (currentItems.length === 0) {
          return "NO Data available";
        }
      } catch (error) {
        console.error("Error deleting report:", error);
        alert("Failed to delete report. Please check your credentials.");
      } finally {
        setDeleteLoading((prev) => ({ ...prev, [id]: false }));
      }
    }
  };

  const handleEdit = (report) => {
    navigate("/Schedule", { state: { report } });
  };

  const navigate = useNavigate();

  const handleAdd = () => {
    navigate("/Schedule");
  };

  const handleRowClick = (report) => {
    setSelectedReport(
      selectedReport && selectedReport.id === report.id ? null : report
    );
  };

  const renderStatusIcon = (report) => {
    switch (report) {
      case "COMPLETED":
        return <i className="fa-solid fa-check-circle status-icon success"></i>;
      case "RUNNING":
        return <i className="fa-solid fa-clock status-icon pending"></i>;
      case "FAILED":
        return <i className="fa-solid fa-times-circle status-icon failure"></i>;
      default:
        return (
          <i className="fa-solid fa-circle-question status-icon default"></i>
        );
    }
  };

  return (
    <div className="table_container">
      <div className="report-list">
        <div className="header-item">
          <h1>Reports</h1>
          <div className="report_container">
            <ToggleButtonGroup
              value={alignment}
              exclusive
              onChange={handleChange}
              aria-label="Platform"
            >
              <ToggleButton
                value="Vamanit"
                sx={{
                  backgroundColor: alignment === "Vamanit",
                  border: "1px solid #3725dddc",
                  color: "#3725dddc",
                  fontWeight: "700",
                  height: "35px",
                  borderRadius: "5px",
                  textTransform: "capitalize",
                  "&:hover": {
                    backgroundColor: "transparent",
                  },
                  "&.Mui-selected": {
                    color: "white",
                    backgroundColor: "#3725dddc",
                    "&:hover": {
                      backgroundColor: "#3725dddc",
                    },
                  },
                }}
              >
                <Typography sx={{ fontWeight: "600" }}>
                  Vamanit Reports
                </Typography>
              </ToggleButton>

              <ToggleButton
                value="Horizon"
                sx={{
                  backgroundColor: alignment === "Horizon",
                  color: "#3725dddc",
                  border: "1px solid #3725dddc",
                  fontWeight: "700",
                  height: "35px",
                  borderRadius: "5px",
                  textTransform: "capitalize",
                  "&:hover": {
                    backgroundColor: "transparent",
                  },
                  "&.Mui-selected": {
                    color: "white",
                    backgroundColor: "#3725dddc",
                    "&:hover": {
                      backgroundColor: "#3725dddc",
                    },
                  },
                }}
              >
                <Typography sx={{ fontWeight: "600" }}>
                  Horizon Reports
                </Typography>
              </ToggleButton>
            </ToggleButtonGroup>
          </div>
        </div>
        {isLoading ? (
          <div className="flex flex-col items-center justify-center">
            <img
              src={Loading}
              alt="Loading..."
              className="w-12 h-12 animate-spin"
            />
            <p className="mt-4 text-lg text-gray-600">Loading...</p>
          </div>
        ) : (
          <>
            <table className="tableRow">
              <thead>
                <tr>
                  <th>S.No</th>
                  <th>User Name</th>
                  <th>Report Name</th>
                  <th>Time</th>
                  <th>Schedule Type</th>
                  <th>Receiver</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {currentItems.length === 0 ? (
                  <tr>
                    <td colSpan={8}>No Reports Found</td>
                  </tr>
                ) : (
                  currentItems.map((report, index) => (
                    <React.Fragment key={report.id}>
                      <tr onClick={() => handleRowClick(report)}>
                        <td>{index + 1 + (currentPage - 1) * itemsPerPage}</td>
                        <td>
                          <span className="user_tooltip">
                            <div className="user_circle">
                              {report.userEmail.charAt(0).toUpperCase()}
                            </div>
                            <span className="user_tooltiptext">
                              {report.userEmail || "N/A"}
                            </span>
                          </span>
                        </td>
                        <td>{report.reportName}</td>
                        <td>{report.time}</td>
                        <td>{report.schedule_type}</td>
                        <td>
                          <span className="tooltip">
                            <div className="circle">
                              {report.receiverEmail.charAt(0).toUpperCase()}
                            </div>
                            {/* <span className="tooltiptext">{report.receiverEmail  || 'N/A'}</span> */}
                          </span>
                        </td>
                        <td>{renderStatusIcon(report.status)}</td>
                        <td>
                          <button
                            className="edit-button"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleEdit(report);
                            }}
                          >
                            <i className="fa-solid fa-pen-to-square"></i>
                          </button>
                          <button
                            className="delete-button"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleDelete(report.id);
                            }}
                            disabled={deleteLoading[report.id]} // Disable the button if loading
                          >
                            {deleteLoading[report.id] ? (
                              <CircularProgress size={16} color="inherit" sx={{color:"red"}} />
                            ) : (
                              <i className="fa-solid fa-trash"></i>
                            )}
                          </button>
                        </td>
                      </tr>
                      {selectedReport && selectedReport.id === report.id && (
                        <tr className="accordion-row">
                          <td colSpan="8" className="accordion-details">
                            <div>
                              <strong>Created On: </strong>
                              <span>{report.schedule_date}</span> |
                              <strong>Delivered On: </strong>
                              <span>{report.time_duration}</span> |
                              <strong>Receiver-Email: </strong>
                              <span>{report.receiverEmail}</span> |
                            </div>
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  ))
                )}
              </tbody>
            </table>
            <div className="pagination">
              <button
                onClick={() => paginate(currentPage - 1)}
                disabled={currentPage === 1}
              >
                Prev
              </button>
              {Array.from({ length: totalPages }, (_, index) => (
                <button
                  key={index + 1}
                  onClick={() => paginate(index + 1)}
                  className={currentPage === index + 1 ? "active" : ""}
                >
                  {index + 1}
                </button>
              ))}
              <button
                onClick={() => paginate(currentPage + 1)}
                disabled={currentPage === totalPages}
              >
                Next
              </button>
            </div>
            <div className="add-report-container">
              <button onClick={handleAdd} className="add-report-button">
                <i className="fa-solid fa-plus"></i>
                <span> New </span>
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default ReportList;
