import React, { useState, useEffect, useContext } from "react";
import { toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "./UserManagement.css";
import { Search } from 'lucide-react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  MenuItem,
  Select,
  CircularProgress,
  FormControl,
  InputLabel,
} from "@mui/material";

import Loading from "../../images/loading.png";
import { PoolContext } from "../../Context/PoolContext";

import axiosInstance from "Services/AxiosInstane";
const UserManagement = () => {
  const [activeTab, setActiveTab] = useState("roles");
  const [users, setUsers] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [filteredUsers, setFilteredUsers] = useState([]);
  const [role, setRole] = useState("");
  const [components, setComponents] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [fetchroles, setFetchroles] = useState([]);
  const [userPermissions, setUserPermissions] = useState([]);
  const [showRoleDialog, setShowRoleDialog] = useState(false);
  const [selectedRole, setSelectedRole] = useState("");
  const [userRoles, setUserRoles] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingStates, setLoadingStates] = useState({
    addRole: false,
    deleteRole: null, // Will store the role being deleted
    submit: false,
    assignRole: false,
    removeRole: null, // Will store the role being removed
  });
  const [isComponentsLoading, setIsComponentsLoading] = useState(false);
  const [userRolesLoading, setUserRolesLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [filteredComponents, setFilteredComponents] = useState([]);

  const componentCategories = {
    Dashboard: ["Overview", "Hosts", "Data Stores", "VMS"],
    Reports: ["Template", "Horizon Reports", "Vamanit Dass Reports"],
    Schedule: ["Schedule"],
    Pools: ["Pools"],
    Settings: ["TOTP", "Domain", "Cluster", "SSL", "SMTP", "RBAC"]
  };

  // Function to get all components
  const getAllComponents = () => {
    return Object.values(componentCategories).flat();
  };

  // Updated List_of_Components to be dynamic based on navigation
  const List_of_Components = getAllComponents();
  // Function to filter components by category
  const filterComponentsByCategory = (category) => {
    if (!category) {
      setFilteredComponents(List_of_Components);
    } else {
      setFilteredComponents(componentCategories[category] || []);
    }
  };

  // Effect to update filtered components when category changes
  useEffect(() => {
    filterComponentsByCategory(selectedCategory);
  }, [selectedCategory]);

  // Component category selection handler
  const handleCategorySelect = (category) => {
    setSelectedCategory(category === selectedCategory ? null : category);
  };
  const pc = useContext(PoolContext);
  const token = pc.token;

  const fetchUsers = async () => {
  setIsLoading(true);
  try {
    const response = await axiosInstance.get(
      `${process.env.REACT_APP_BACKEND_URL}/v1/guacamole/list_users`,
      {
        headers: {
          Authorization: `Bearer ${token}`, // Include the Bearer token in the Authorization header
        },
      }
    );

    if (response.data?.data) {
      const usernames = response.data.data.map((user) => user.username);
      setUsers(usernames);
      setFilteredUsers(usernames);
    }
  } catch (error) {
    showError("Failed to fetch users");
  } finally {
    setIsLoading(false);
  }
};
const fetchRoles = async () => {
  setIsLoading(true);
  try {
    const response = await axiosInstance.get(
      `${process.env.REACT_APP_BACKEND_URL}/v1/guacamole/get_client_roles`,
      {
        headers: {
          Authorization: `Bearer ${token}`, // Include the Bearer token in the Authorization header
        },
      }
    );

    if (response.data?.client_roles) {
      setFetchroles(response.data.client_roles);
    }
  } catch (error) {
    showError("Failed to fetch roles");
  } finally {
    setIsLoading(false);
  }
};

  const fetchUserPermissions = async () => {
    // try {
    //   const response = await fetch(
    //     `${process.env.REACT_APP_BACKEND_URL}/v1/guacamole/list_users/${selectedUser}`,
    //     {
    //       headers: {
    //         Authorization: `Bearer ${token}`, // Include the Bearer token in the Authorization header
    //       },
    //     }
    //   );
    //   const data = await response.json();
    //   setUserPermissions(data);
    //   setRole(data.role || "");
    //   setComponents(data.components || []);
    // } catch (error) {}
  };

  useEffect(() => {
    fetchUsers();
    fetchRoles();
  }, []);

  useEffect(() => {
    if (selectedUser) {
      fetchUserPermissions();
    } else {
      setUserPermissions(null);
      setRole("");
      setComponents([]);
    }
  }, [selectedUser]);

  const showError = (message) => {
    toast.error(message);
  };

  const showSuccess = (message) => {
    toast.success(message);
  };

  const handleSearch = (term) => {
    setSearchTerm(term);
    const results = term
      ? users.filter((user) => user.toLowerCase().includes(term.toLowerCase()))
      : users;
    setFilteredUsers(results);
  };

  const handleUserClick = async (username) => {
    setSelectedUser((prevSelected) => {
      const newSelected = prevSelected === username ? null : username;
      if (newSelected) {
        GetuserPermission(newSelected);
      } else {
        setUserRoles([]);
      }
      return newSelected;
    });
  };

  const fetchRoleComponents = async (selectedRole) => {
    setIsComponentsLoading(true);
    try {
      const response = await axiosInstance.get(
        `${process.env.REACT_APP_BACKEND_URL}/v1/guacamole/get_role_components/${selectedRole}`,
        {
          headers: {
            Authorization: `Bearer ${token}`, // Include the Bearer token in the Authorization header
          },
        }
      );
  
      if (response.data?.components) {
        setComponents(response.data.components);
      } else {
        setComponents([]);
      }
    } catch (error) {
      console.error("Failed to fetch role components", error);
      setComponents([]);
    } finally {
      setIsComponentsLoading(false);
    }
  };

  const handleRoleSelect = (selectedRole) => {
    let testrole = "";
    // If clicking the same role that's currently selected, deselect it
    if (role === selectedRole) {
      setRole("");
      setComponents([]);
      return;
    } else {
      testrole = selectedRole;
    }
    // Otherwise, select the new role and fetch its components
    // setRole(selectedRole);

    setRole(testrole);

    fetchRoleComponents(selectedRole);
  };

  const handleComponentChange = (component) => {
    setComponents((prev) => {
      // If the component is already included, remove it
      if (prev.includes(component)) {
        return prev.filter((c) => c !== component);
      }
      // If the component is not included and we have a role selected, add it
      if (role) {
        return [...prev, component];
      }
      return prev;
    });
  };

  // Modified handlers with loading states
  const handleAddRole = async () => {
    if (!role.trim()) {
      showError("Please enter a role name");
      return;
    }
  
    setLoadingStates((prev) => ({ ...prev, addRole: true }));
    try {
      const response = await axiosInstance.post(
        `${process.env.REACT_APP_BACKEND_URL}/v1/guacamole/post_role/${role}`,
        {},
        {
          headers: {
            Authorization: `Bearer ${token}`, // Include the Bearer token in the Authorization header
          },
        }
      );
  
      if (response.status === 200) {
        showSuccess("Role added successfully!");
        setFetchroles([...fetchroles, role]);
        setRole("");
      } else if (response.status === 400 && response.data.detail === "Role already exists") {
        showError("Role already exists");
      }
    } catch (error) {
      showError("Failed to add role");
    } finally {
      setLoadingStates((prev) => ({ ...prev, addRole: false }));
    }
  };

  const handleDelete = async (roleToDelete) => {
    setLoadingStates((prev) => ({ ...prev, deleteRole: roleToDelete }));
    try {
      const response = await axiosInstance.delete(
        `${process.env.REACT_APP_BACKEND_URL}/v1/guacamole/delete_role/${roleToDelete}`,
        {
          headers: {
            Authorization: `Bearer ${token}`, // Include the Bearer token in the Authorization header
          },
        }
      );
  
      if (response.status === 200) {
        showSuccess("Role deleted successfully!");
        setFetchroles(fetchroles.filter((r) => r !== roleToDelete));
      }
    } catch (error) {
      showError("Failed to delete role");
    } finally {
      setLoadingStates((prev) => ({ ...prev, deleteRole: null }));
    }
  };

  const handleSubmit = async () => {
    if (!role) {
      showError("Please select a role");
      return;
    }
  
    setLoadingStates((prev) => ({ ...prev, submit: true }));
    try {
      const response = await axiosInstance.post(
        `${process.env.REACT_APP_BACKEND_URL}/v1/guacamole/submit_role_components`,
        {
          role: role,
          components: components,
        },
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`, // Include the Bearer token in the Authorization header
          },
        }
      );
  
      if (response.status === 200) {
        showSuccess("Role and components saved successfully");
        await fetchRoles();
        setComponents([]);
        setRole("");
      } else {
        throw new Error(response.data?.detail || "Failed to save role and components");
      }
    } catch (error) {
      showError(error.message || "Failed to save role and components");
    } finally {
      setLoadingStates((prev) => ({ ...prev, submit: false }));
    }
  };

  const GetuserPermission = async (username) => {
    setUserRolesLoading(true);
    try {
      const response = await axiosInstance.get(
        `${process.env.REACT_APP_BACKEND_URL}/v1/guacamole/get_user_permissions/${username}`,
        {
          headers: {
            Authorization: `Bearer ${token}`, // Include the Bearer token in the Authorization header
          },
        }
      );
  
      if (response.data.status === "Ok") {
        setUserRoles(response.data.roles || []);
      }
    } catch (error) {
      showError("Failed to fetch user roles");
    } finally {
      setUserRolesLoading(false);
    }
  };



const handleRoleAssignment = async () => {
  if (!selectedRole) {
    showError("Please select a role");
    return;
  }

  if (!selectedUser) {
    showError("Please select a user");
    return;
  }

  setIsLoading(true);
  try {
    const response = await axiosInstance.post(
      `${process.env.REACT_APP_BACKEND_URL}/v1/guacamole/assign_user_role`,
      {
        username: [selectedUser], // Ensure username is sent as a list
        role: selectedRole, // Ensure role is sent as a string
        components: [],
      },
      {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`, // Include the Bearer token in the Authorization header
        },
      }
    );

    if (response.status === 200) {
      await GetuserPermission(selectedUser);
      showSuccess("Role assigned successfully");
      setShowRoleDialog(false);
      setSelectedRole("");
    } else {
      showError(response.data?.detail || "Failed to assign role");
    }
  } catch (error) {
    showError(error.message || "Failed to assign role");
  } finally {
    setIsLoading(false);
  }
};

  const handleAssignRole = () => {
    if (!selectedUser) {
      showError("Please select a user first");
      return;
    }
    setShowRoleDialog(true);
  };
  const removeRoleFromUser = async (username, roleToRemove) => {
    setLoadingStates((prev) => ({ ...prev, removeRole: roleToRemove }));
    try {
      const response = await axiosInstance.delete(
        `${process.env.REACT_APP_BACKEND_URL}/v1/guacamole/remove_role_from_user`,
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`, // Include the Bearer token in the Authorization header
          },
          data: {
            username: [username],
            role: roleToRemove,
            components: [],
          },
        }
      );
  
      if (response.status === 200) {
        showSuccess("Role removed successfully");
        // Refresh user roles
        await GetuserPermission(username);
      } else {
        showError(response.data?.detail || "Failed to remove role");
      }
    } catch (error) {
      showError(error.message || "Failed to remove role");
    } finally {
      setLoadingStates((prev) => ({ ...prev, removeRole: null }));
    }
  };

  return (
    <div className="w-[95%] mx-auto p-8 bg-white rounded-lg shadow-lg h-[91vh]">
      <div className="bg-white  p-6  w-full">
        {/* Tabs */}
        <div className="flex justify-between items-center mb-6 w-full">
          <div className="relative border-b mb-6 w-full">
            <div className="flex gap-6">
              <button
                className={`pb-3 px-6 font-semibold text-sm relative transition-all duration-300 ${
                  activeTab === "roles"
                    ? "text-indigo-600 after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-full after:h-1 after:bg-indigo-600 after:rounded after:transition-transform after:duration-500"
                    : "text-gray-600 hover:text-indigo-600"
                }`}
                onClick={() => setActiveTab("roles")}
              >
                Role Management
              </button>
              <button
                className={`pb-3 px-6 font-semibold text-sm relative transition-all duration-300 ${
                  activeTab === "users"
                    ? "text-indigo-600 after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-full after:h-1 after:bg-indigo-600 after:rounded after:transition-transform after:duration-500"
                    : "text-gray-600 hover:text-indigo-600"
                }`}
                onClick={() => setActiveTab("users")}
              >
                User Roles
              </button>
            </div>
          </div>
        </div>

        {/* Role Management Tab */}
        {activeTab === "roles" && (
          <div className="flex flex-col gap-6">
            {/* Add Role Input */}
            <div className="flex items-center gap-4 w-3/4">
              <input
                type="text"
                placeholder="Enter role..."
                value={role}
                onChange={(e) => setRole(e.target.value)}
                className="flex-1 p-2 border rounded-md focus:ring-2 focus:ring-indigo-700 focus:border-indigo-700 outline-none transition-all duration-200"
                disabled={loadingStates.addRole}
              />
              <button
                onClick={handleAddRole}
                disabled={loadingStates.addRole}
                className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-800 transition-colors duration-200 shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loadingStates.addRole ? (
                  <span className="flex items-center gap-2">
                    <CircularProgress size={16} color="inherit" />
                    Creating...
                  </span>
                ) : (
                  "Create Role"
                )}
              </button>
            </div>

            {/* Add Role and Components Section */}
            <div className="flex ">
              {/* Role List */}
              <div className="flex flex-col gap-4 flex-1">
                <div className="overflow-hidden border rounded-md p-4 shadow-inner bg-white w-4/6">
                  <div className="mb-2">
                    <label className="block font-medium text-gray-700">
                      Roles
                    </label>
                    <div className="line mt-1"></div>
                  </div>
                  <div className="h-[48vh] overflow-y-auto custom-scrollbar">
                    {isLoading ? (
                      <div className="flex justify-center items-center h-full">
                        <img
                          src={Loading}
                          alt="Loading..."
                          className="w-12 h-12 animate-spin"
                        />
                      </div>
                    ) : (
                      fetchroles.map((roleItem, index) => (
                        <div
                          key={index}
                          className="flex items-center justify-between p-2 hover:bg-gray-50 transition-colors duration-150 border-b last:border-none"
                        >
                          <div key={index} className="flex items-center gap-4">
                            <input
                              type="radio"
                              id={`role-${index}`}
                              name="roleSelection"
                              onChange={() => handleRoleSelect(roleItem)}
                              checked={role === roleItem}
                              className="text-indigo-600 focus:ring-indigo-500"
                            />
                            <label
                              htmlFor={`role-${index}`}
                              className="cursor-pointer"
                            >
                              {roleItem}
                            </label>
                          </div>

                          <button
                            onClick={() => handleDelete(roleItem)}
                            disabled={loadingStates.deleteRole === roleItem}
                            className="text-red-500 hover:text-red-700 disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            {loadingStates.deleteRole === roleItem ? (
                              <CircularProgress size={16} color="inherit" />
                            ) : (
                              <i className="fa-solid fa-trash"></i>
                            )}
                          </button>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </div>
              <div className="flex-1">
                <div className="border rounded-md p-4 space-y-2 shadow-inner bg-white w-5/6">
                  <div className="mb-2">
                    <label className="block font-medium text-gray-700">
                      Components
                    </label>
                    <div className="line mt-1"></div>
                  </div>

                  {/* Category buttons */}
                  <div className="flex flex-wrap gap-2 mb-4">
                    {Object.keys(componentCategories).map((category) => (
                      <button
                        key={category}
                        onClick={() => handleCategorySelect(category)}
                        className={`px-3 py-1 rounded-md text-sm ${
                          selectedCategory === category
                            ? 'bg-indigo-600 text-white'
                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                        }`}
                      >
                        {category}
                      </button>
                    ))}
                  </div>

                  <div className="h-[44vh] overflow-y-auto custom-scrollbar border-b last:border-none">
                    {isComponentsLoading ? (
                      <div className="flex justify-center items-center h-full">
                        <img
                          src={Loading}
                          alt="Loading..."
                          className="w-12 h-12 animate-spin"
                        />
                      </div>
                    ) : (
                      (selectedCategory ? filteredComponents : List_of_Components).map((component, index) => (
                        <div
                          key={index}
                          className="flex items-center gap-5 hover:bg-gray-50 p-2 transition-colors duration-150 border-b last:border-none"
                        >
                          <input
                            type="checkbox"
                            id={`component-${index}`}
                            checked={components.includes(component)}
                            onChange={() => handleComponentChange(component)}
                            className="rounded border-gray-300 text-indigo-700 focus:ring-indigo-700 mt-1"
                            disabled={!role}
                          />
                          <label
                            htmlFor={`component-${index}`}
                            className="select-none mt-1"
                          >
                            {component}
                          </label>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </div>
            </div>
            <div className=" flex justify-between">
              <div className="flex justify-between mt-4">
                <button
                  onClick={() => {
                    setRole(""); // Clear the role selection
                    setComponents([]); // Clear the components
                  }}
                  className="text-white bg-indigo-600 hover:bg-indigo-500 px-2 py-2 rounded"
                >
                  Clear Selection
                </button>
              </div>
              <div className="flex justify-between mt-4 mr-[7rem]">
              <button
                      onClick={handleSubmit}
                      disabled={loadingStates.submit || !role}
                      className="w-full px-6 py-2 bg-indigo-600 text-white rounded-md transition-colors duration-200 shadow-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-indigo-700"
                    >
                      {loadingStates.submit ? (
                        <span className="flex items-center justify-center gap-2">
                          <CircularProgress size={16} color="inherit" />
                          Saving...
                        </span>
                      ) : (
                        "Submit"
                      )}
                    </button>
              </div>
            </div>
          </div>
        )}

        {/* User Roles Tab */}
        {activeTab === "users" && (
          <div className="grid grid-cols-2 gap-6">
            {/* Left side - User list */}
            <div className="text-left">
              <div className="relative">
                <input
                  type="text"
                  placeholder="Search users..."
                  value={searchTerm}
                  onChange={(e) => handleSearch(e.target.value)}
                  className="w-full p-2 pr-10 mb-4 border rounded-md focus:ring-2 focus:ring-indigo-700 focus:border-indigo-700 outline-none transition-all duration-200"
                />
                <div className="absolute right-3 top-1/3 -translate-y-1/2 text-gray-400 text-xl">
                
                  <Search size={18} />
                </div>
              </div>
              <div className="h-[60vh] overflow-y-auto border rounded-md shadow-inner bg-white custom-scrollbar">
                {isLoading ? (
                  <div className="flex justify-center items-center h-full">
                    <img
                      src={Loading}
                      alt="Loading..."
                      className="w-12 h-12 animate-spin"
                    />
                  </div>
                ) : (
                  filteredUsers.map((user, index) => (
                    <div
                      key={index}
                      className={`p-3 cursor-pointer border-b-2 border-gray-200 hover:border-b-0 hover:bg-indigo-100 hover:border-l-4 hover:border-indigo-500  transition-all duration-150 ${
                        selectedUser === user
                          ? "bg-indigo-50 text-indigo-700"
                          : ""
                      }`}
                      onClick={() => handleUserClick(user)}
                    >
                      {user}
                    </div>
                  ))
                )}
              </div>
            </div>

            {/* Right side - User roles */}
            <div>
              <div className="mb-4">
                <div className="flex justify-end h-10">
                  {" "}
                  {/* This div will ensure a fixed height for the button */}
                  {selectedUser ? (
                    <button
                      onClick={handleAssignRole}
                      disabled={loadingStates.assignRole}
                      className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors duration-200 shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {loadingStates.assignRole ? (
                        <span className="flex items-center gap-2">
                          <CircularProgress size={16} color="inherit" />
                          Assigning...
                        </span>
                      ) : (
                        "Assign Role"
                      )}
                    </button>
                  ) : (
                    <span className="px-4 py-2  rounded-md text-center w-full h-full flex items-center justify-center"></span>
                  )}
                </div>
              </div>

              <div className="h-[60vh] overflow-y-auto border rounded-md shadow-inner bg-white p-4 custom-scrollbar">
                {selectedUser ? (
                  <>
                    {userRolesLoading ? (
                      <div className="flex justify-center items-center">
                        <img
                          src={Loading}
                          alt="Loading..."
                          className="w-12 h-12 animate-spin"
                        />
                      </div>
                    ) : userRoles.length > 0 ? (
                      userRoles.map((userRole, index) => (
                        <div
                          key={index}
                          className="p-3 bg-gray-50 rounded-md flex justify-between items-center mb-2"
                        >
                          <li className="text-gray-500">{userRole}</li>
                          <button
                            onClick={() =>
                              removeRoleFromUser(selectedUser, userRole)
                            }
                            disabled={loadingStates.removeRole === userRole}
                            className="text-red-500 hover:text-red-700 disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            {loadingStates.removeRole === userRole ? (
                              <CircularProgress size={16} color="inherit" />
                            ) : (
                              <i className="fa-solid fa-trash"></i>
                            )}
                          </button>
                        </div>
                      ))
                    ) : (
                      <p className="text-gray-500 text-center mt-4">
                        No roles found
                      </p>
                    )}
                  </>
                ) : (
                  <p className="text-gray-500 text-center mt-4">
                    Select a user to view and manage roles
                  </p>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Role Assignment Dialog */}
        <Dialog
          open={showRoleDialog}
          onClose={() => setShowRoleDialog(false)}
          fullWidth
          maxWidth="xs" // Make the dialog smaller
        >
          <DialogTitle sx={{ color: "gray", fontSize: "18px" }}>
            Add Role for {selectedUser}
          </DialogTitle>
          <DialogContent>
            <FormControl fullWidth margin="normal">
              <InputLabel htmlFor="role-select">Select Role</InputLabel>
              <Select
                id="role-select"
                value={selectedRole}
                label="Select Role"
                onChange={(e) => setSelectedRole(e.target.value)}
                disabled={isLoading}
              >
                <MenuItem value="selectrole">
                  {/* <em>Select a role...</em> */}
                </MenuItem>
                {fetchroles.map((role, index) => (
                  <MenuItem key={index} value={role}>
                    {role}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </DialogContent>
          <DialogActions>
            <Button
              onClick={() => setShowRoleDialog(false)}
              disabled={isLoading}
              sx={{
                backgroundColor: "#3725dddc",
                color: "white",
                "&:hover": { backgroundColor: "#3725dd" },
              }}
            >
              Cancel
            </Button>
            <Button
              onClick={handleRoleAssignment}
              color="primary"
              variant="contained"
              disabled={isLoading}
              startIcon={isLoading && <CircularProgress size={20} />}
              sx={{
                backgroundColor: "#3725dddc",
                color: "white",
                "&:hover": { backgroundColor: "#3725dd" },
              }}
            >
              {isLoading ? "Adding..." : "Add Role"}
            </Button>
          </DialogActions>
        </Dialog>

        {/* Submit Button */}
      </div>
    </div>
  );
};

export default UserManagement;
