import { useState, useEffect, useRef } from "react";
import { fetchWorkflows } from "../Tasks/Task"; // Import the extracted function
import { FaTasks, FaRedo, FaMinus, FaExpand, FaCheckCircle} from "react-icons/fa";
import { AiOutlineLoading3Quarters, AiOutlineCloseCircle } from "react-icons/ai";

const Footer = ({ tokenParsed }) => {
  const [data, setData] = useState([]);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const refreshTimerRef = useRef(null);
  const userName = tokenParsed?.preferred_username || "N/A";

  const loadRecentTasks = async () => {
    setIsRefreshing(true);
    try {
      const workflows = await fetchWorkflows(userName);
      
      console.log("All Workflows:", workflows);
      console.log("Current Username:", userName);
      
      const now = new Date().getTime();
      
      // Filter ONLY current user's tasks within last 15 minutes
      const recentWorkflows = workflows.filter((task) => {
        try {
          console.log("Task Initiator:", task.initiator);
          console.log("Current Username:", userName);
          
          const isCurrentUserTask = task.initiator === userName;
          const taskStartTime = new Date(task.startTime).getTime();
          const isRecentTask = now - taskStartTime <= 15 * 60 * 1000; // 15 minutes
          
          console.log("Is Current User Task:", isCurrentUserTask);
          console.log("Is Recent Task:", isRecentTask);
          
          return isCurrentUserTask && isRecentTask;
        } catch (err) {
          console.error("Error parsing task:", task, err);
          return false;
        }
      });
      
      console.log("Recent Workflows:", recentWorkflows);
      
      // Sort by most recent first
      recentWorkflows.sort((a, b) => {
        try {
          return new Date(b.startTime).getTime() - new Date(a.startTime).getTime();
        } catch (err) {
          return 0;
        }
      });
      
      setData(recentWorkflows);
    } catch (error) {
      console.error("Error loading recent tasks:", error);
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    loadRecentTasks();

    refreshTimerRef.current = setInterval(() => {
      loadRecentTasks();
    }, 10000); 

    return () => {
      if (refreshTimerRef.current) {
        clearInterval(refreshTimerRef.current);
      }
    };
  }, [userName]);

  // Rest of the footer component remains the same

  
  return (
    <footer
    className={`fixed bottom-0  text-sm transition-all duration-500 ease-in-out ${
      isExpanded 
        ? "bg-white shadow-lg top-[73%] w-[86.5%] right-[0.8%]" 
        : "w-[86.5%] right-[0.8%] bg-gray-100"
    }`} 
    style={{
      height: isExpanded ? "300px" : "60px",
      // transition: "max-height 10s ease-in-out" // Smooth height transition
    }}
    
    >
      {/* Header */}
      <div className="flex justify-between items-center bg-[#3725dddc] px-2 py-2">
      <div className="flex items-center space-x-2">
        <FaTasks className="text-white" size={16} /> 
          <span className="text-white rounded-md font-bold">Recent Tasks</span>
      </div>
        <div className="flex space-x-4">
          <FaRedo
            // className={`cursor-pointer text-white hover:text-gray-300 ${isRefreshing ? "animate-spin" : ""}`}
            className="cursor-pointer text-white hover:text-gray-300"

            size={14}
            onClick={loadRecentTasks}
          />
          {isExpanded ? (
            <FaMinus className="cursor-pointer text-white hover:text-gray-300" size={14} onClick={() => setIsExpanded(false)} />
          ) : (
            <FaExpand className="cursor-pointer text-white hover:text-gray-300" size={14} onClick={() => setIsExpanded(true)} />
          )}
        </div>
      </div>

      {/* Table */}
      {isExpanded && (
        <div className="w-[100%] bg-white ">
          <div className="max-h-[220px] overflow-y-auto custom-scrollbar">
            <table className="w-full border-collapse">
        
            {/* ✅ Fixed Header */}
              <thead className="sticky top-0 ">
                <tr className="text-gray border-b border-gray-400 font-bold uppercase text-xs leading-normal">
                  <th className="py-2 px-3">S.No</th>
                  <th className="py-2 px-3">Task Name</th>
                  <th className="py-2 px-3">Action</th>
                  <th className="py-2 px-3">Status</th>
                  <th className="py-2 px-3">Duration</th>
                  <th className="py-2 px-3">Start Time</th>
                  <th className="py-2 px-3">End Time</th>
                </tr>
              </thead>

              <tbody>
                {data.length > 0 ? (
                  data.map((task, index) => (
                  //   <tr 
                  //   key={index} 
                  //   className={`text-center ${
                  //     index !== data.length - 1 ? "border-b border-gray-200" : "" // No border on last row
                  //   }`}
                  // >
                  <tr key={index} className="text-center border-b border-gray-200"> 
                      <td className="py-2 px-3"> {index+1} </td>
                      <td className="py-2 px-3"> {task.taskName} </td>
                      <td className="py-2 px-3"> {task.action} </td>
                      <td className="py-2 px-3 font-semibold flex items-center justify-center gap-1">
                        {task.status === "Completed" && (
                          <span className="text-green-600 flex items-center gap-1">
                            <FaCheckCircle className="text-green-500 text-sm" /> {task.status}
                          </span>
                        )}
                        {task.status === "Running" && (
                          <span className="text-blue-600 flex items-center gap-1">
                            <AiOutlineLoading3Quarters className="animate-spin text-blue-500 text-sm" /> {task.status}
                          </span>
                        )}
                        {task.status === "Failed" && (
                          <span className="text-red-600 flex items-center gap-1">
                            <AiOutlineCloseCircle className="text-red-500 text-sm" /> {task.status}
                          </span>
                        )}
                      </td>
                      <td className="py-2 px-3">{task.duration}</td>
                      <td className="py-2 px-3">{task.startTime}</td>
                      <td className="py-2 px-3">{task.endTime}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="6" className="p-2 text-center text-gray-500">
                      No recent tasks available
                    </td>
                  </tr>
                )}
              </tbody>
      </table>
    </div>
  </div>
)}
        {/* Condensed View */}
        {!isExpanded && data.length > 0 && (
          <div className="px-2 py-1 text-xs">
            <span>
              Last task: <strong>{data[0].taskName}</strong> -{" "}
              <span className={data[0].status === "Completed" ? "text-green-600" : "text-red-600"}>
                {data[0].status}
              </span>
            </span>
          </div>
        )}
      </footer>
    );
  };

  export default Footer;