import React, { useState, useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { ChevronRightIcon } from "@heroicons/react/24/outline";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faAngleRight,
  faTimes,
  faTachometerAlt,
  faChartBar,
  faCog,
  faCalendarAlt,
  faLayerGroup,
  faTable,
} from "@fortawesome/free-solid-svg-icons";
import Beta from "../Beta/Beta";
import Thinkcloud from "../../images/t3.jpg";
import { useRbac } from "../../Context/RBAC Context";
import "./Sidebar.css";

function classNames(...classes) {
  return classes.filter(Boolean).join(" ");
}

const Sidebar = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [isToggled, setIsToggled] = useState(true);
  const [openSubMenu, setOpenSubMenu] = useState(null);
  const [iconMenuPosition, setIconMenuPosition] = useState({ top: 0, left: 0 });
  const [showIconSubmenu, setShowIconSubmenu] = useState(false);
  const [activeIconItem, setActiveIconItem] = useState(null);

  const { navigation, loading } = useRbac();

  useEffect(() => {
    const currentPath = location.pathname;
    navigation.forEach((item) => {
      item.current = item.href === currentPath;
      if (item.submenus) {
        item.submenus.forEach((subitem) => {
          subitem.current = subitem.href === currentPath;
        });
      }
    });
  }, [location.pathname, navigation]);

  const handleSubMenuClick = (name) => {
    setOpenSubMenu(openSubMenu === name ? null : name);
  };
    const handleMenuItemClick = (item) => {
    if (item.submenus) {
      // Toggle submenu open/close
      handleSubMenuClick(item.name);
    } else {
      // If it's not a submenu, navigate to the clicked page
      navigate(item.href);
      // Update the current property for top-level menu items
      navigation.forEach((menuItem) => {
        menuItem.current = menuItem === item;
        if (menuItem.submenus) {
          // Update the current property for submenu items
          menuItem.submenus.forEach((submenuItem) => {
            submenuItem.current = submenuItem === item;
          });
        }
      });
    }
  };
  const handleIconClick = (event, item) => {
    event.stopPropagation();
    if (item.submenus) {
      const rect = event.currentTarget.getBoundingClientRect();
      setIconMenuPosition({
        top: rect.top,
        left: rect.right + 5, // Reduced the offset from 10 to 5
      });
      setActiveIconItem(item);
      setShowIconSubmenu(true);
    } else {
      navigate(item.href);
      setShowIconSubmenu(false);
    }
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (showIconSubmenu && !event.target.closest(".sidebar-icon-submenu")) {
        setShowIconSubmenu(false);
      }
    };

    document.addEventListener("click", handleClickOutside);
    return () => document.removeEventListener("click", handleClickOutside);
  }, [showIconSubmenu]);

  const toggleSlide = () => {
    setIsToggled(!isToggled);
    setShowIconSubmenu(false);
  };

 
  return (
    <div className="sidebar-container h-screen flex flex-col">
      <div
        onClick={toggleSlide}
        className="sidebar-toggle bg-indigo-600 p-2 text-white flex justify-end cursor-pointer shrink-0"
      >
        {isToggled ? (
          <FontAwesomeIcon icon={faTimes} />
        ) : (
          <div
            className="sidebar-logo"
            style={{
              width: "55px",
              height: "40px",
              backgroundImage: `url(${Thinkcloud})`,
              backgroundSize: "100% 100%",
              backgroundRepeat: "no-repeat",
              borderRadius: "5px",
            }}
            alt="Thinkcloud Logo"
          />
        )}
      </div>
      {isToggled ? (
        <div className="relative flex-1 overflow-hidden">
          <div className="h-full bg-indigo-600 text-white w-64 shrink-0 z-30 inset-y-0 left-0 transform -translate-x-full md:translate-x-0 transition-transform duration-200 ease-in overflow-y-auto">
            <div className="py-7 px-2">
              <div className="flex flex-shrink-0 items-center justify-center w-full mb-6">
                <img
                  className="w-auto m-1 image_container"
                  src={Thinkcloud}
                  alt="Thinkcloud logo"
                />
              </div>
              <nav className="flex flex-col gap-2">
                {navigation.map((item) => (
                  <React.Fragment key={item.name}>
                    <div
                      onClick={() => handleMenuItemClick(item)}
                      className={classNames(
                        item.current
                          ? "bg-indigo-700"
                          : "hover:bg-indigo-700 hover:text-slate-300",
                        "menu-item rounded-md px-3 py-2 text-base font-medium flex items-center justify-between cursor-pointer"
                      )}
                    >
                      {item.name}
                      {item.submenus && (
                        <ChevronRightIcon
                          className={`menu-icon h-5 w-5 transition-transform ${
                            openSubMenu === item.name ? "rotate-90" : ""
                          }`}
                        />
                      )}
                      {item.beta && <Beta />}
                    </div>
                    {item.submenus && (
                      <div
                        className={`pl-6 transition-all duration-300 ease-in-out overflow-hidden ${
                          openSubMenu === item.name ? "max-h-96" : "max-h-0"
                        }`}
                      >
                        {item.submenus.map((subitem) => (
                          <li
                            key={subitem.name}
                            onClick={() => handleMenuItemClick(subitem)}
                            className={classNames(
                              subitem.current
                                ? "bg-indigo-600"
                                : "hover:bg-indigo-700 hover:text-slate-300",
                              "rounded-md px-3 py-2 text-base font-medium text-white w-full text-left cursor-pointer"
                            )}
                          >
                            <span className="inline-flex">
                              {subitem.name}
                              {subitem.beta && <Beta />}
                            </span>
                          </li>
                        ))}
                      </div>
                    )}
                  </React.Fragment>
                ))}
              </nav>
            </div>
          </div>
        </div>
      ) : (
        <div className="bg-indigo-600 p-4 text-white flex flex-1 relative ">
          <div className="flex flex-col items-center gap-6">
            {navigation.map((item) => (
              <FontAwesomeIcon
                key={item.name}
                icon={getIcon(item.name)}
                title={item.name}
                className="sidebar-icon cursor-pointer"
                onClick={(e) => handleIconClick(e, item)}
              />
            ))}
          </div>
          {showIconSubmenu && activeIconItem && activeIconItem.submenus && (
            <div
              className="sidebar-icon-submenu absolute bg-indigo-700 rounded-md py-1 z-50 text-sm"
              style={{
                top: `${iconMenuPosition.top}px`,
                left: `${iconMenuPosition.left}px`,
                width: "120px",
                maxHeight: "200px",
                overflowY: "auto",
              }}
            >
              {activeIconItem.submenus.map((subitem) => (
                <div
                  key={subitem.name}
                  onClick={() => handleMenuItemClick(subitem)}
                  className="px-3 py-1.5 hover:bg-indigo-600 cursor-pointer whitespace-nowrap overflow-hidden text-ellipsis"
                >
                  {subitem.name}
                  {subitem.beta && <Beta />}
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

const getIcon = (name) => {
  const icons = {
    Dashboard: faTachometerAlt,
    Reports: faTable,
    Schedule: faCalendarAlt,
    Pools: faLayerGroup,
    Settings: faCog,
  };
  return icons[name] || faAngleRight;
};

export default Sidebar;
