import { useState, useEffect, useContext } from "react";
import axiosInstance from "Services/AxiosInstane";
import { PoolContext } from "../../Context/PoolContext";
import { FaCheckCircle } from "react-icons/fa";
import { AiOutlineLoading3Quarters, AiOutlineCloseCircle} from "react-icons/ai";
import Loading from "../../images/loading.png";
import "./Task.css";

export const fetchWorkflows = async (userName) => {
  try {
    const response = await axiosInstance.get(`${process.env.REACT_APP_BACKEND_URL}/v1/workflows`);
    if (!response.data || !response.data.workflows) return [];

    return response.data.workflows
      .filter(workflow => workflow.workflow_type && !/^get/i.test(workflow.workflow_type))
      .map((workflow, index) => ({
        sNo: index + 1,
        taskName: workflow.task_name || "N/A",
        action: workflow.action || "N/A",
        status: workflow.status ? workflow.status.charAt(0).toUpperCase() + workflow.status.slice(1).toLowerCase() : "Unknown",
        initiator: workflow.UserName || "N/A",
        duration: workflow.execution_time ? `${workflow.execution_time}` : "-",
        startTime: workflow.start_time ? `${workflow.start_time}` : "-",
        endTime: workflow.close_time ? `${workflow.close_time}` : "Ongoing",
      }));
  } catch (error) {
    console.error("Error fetching workflows:", error);
    return [];
  }
};

const SkeletonLoader = () => (
  <tr>
    {[...Array(8)].map((_, i) => (  
      <td key={i} className="py-4 px-3">
        <div className="h-6 w-24 bg-gray-200 rounded animate-pulse"></div>
      </td>
    ))}
  </tr>
);

const Tasks = (props) => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  let userName = props.tokenParsed.name;
  const pc = useContext(PoolContext);

  useEffect(() => {
    const getTasks = async () => {
      setLoading(true);
      const tasks = await fetchWorkflows(userName);
      setData(tasks);
      setLoading(false);
    };
    getTasks();
  }, [userName]);

  return (
    <div className="p-6 h-screen">
      <div className="max-w-[95%] h-[85vh] mx-auto bg-white rounded-lg p-4 shadow-md flex flex-col">
        <h2 className="text-lg font-semibold text-center text-gray-700 mb-4">Task List</h2>
        <div className="max-h-[80vh] flex-1 overflow-y-auto rounded-md bg-white custom-scrollbar">
          <table className="min-w-full bg-white text-sm border-collapse">
            <thead className="bg-indigo-600 text-white font-bold uppercase text-xs leading-normal sticky top-0 z-10">
              <tr>
                <th className="py-2 px-3">S.No</th>
                <th className="py-2 px-3">Task Name</th>
                <th className="py-2 px-3">Action</th>
                <th className="py-2 px-3">Status</th>
                <th className="py-2 px-3">Initiator</th>
                <th className="py-2 px-3">Duration</th>
                <th className="py-2 px-3">Start Time</th>
                <th className="py-2 px-3">End Time</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                [...Array(5)].map((_, index) => <SkeletonLoader key={index} />)
              ) : data.length > 0 ? (
                data.map((task, index) => (
                  <tr key={index} className="text-center border-b border-gray-200">
                    <td className="py-2 px-3">{task.sNo}</td>
                    <td className="py-2 px-3">{task.taskName}</td>
                    <td className="py-2 px-3">{task.action}</td>
                    <td className="py-2 px-3 font-semibold flex items-center justify-center gap-1">
                      {task.status === "Completed" && (
                        <span className="text-green-600 flex items-center gap-1">
                          <FaCheckCircle className="text-green-500 text-sm" /> {task.status}
                        </span>
                      )}
                      {task.status === "Running" && (
                        <span className="text-blue-600 flex items-center gap-1">
                          <AiOutlineLoading3Quarters className="animate-spin text-blue-500 text-sm" /> {task.status}
                        </span>
                      )}
                      {task.status === "Failed" && (
                        <span className="text-red-600 flex items-center gap-1">
                          <AiOutlineCloseCircle className="text-red-500 text-sm" /> {task.status}
                        </span>
                      )}
                    </td>
                    <td className="py-2 px-3">{task.initiator}</td>
                    <td className="py-2 px-3">{task.duration}</td>
                    <td className="py-2 px-3">{task.startTime}</td>
                    <td className="py-2 px-3">{task.endTime}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="8" className="text-center py-4 text-gray-500">
                    No tasks available
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Tasks;
