import "./SmtpConfig.css";
import React, { useState ,useContext ,useEffect} from 'react';
import {Link} from 'react-router-dom';
import TextField from '@mui/material/TextField';
import { Checkbox, FormControlLabel, FormGroup, Button,Radio,RadioGroup, Switch, Dialog,DialogContent,DialogTitle,DialogActions} from '@mui/material';
// import { Password } from "@mui/icons-material";
import { toast } from "react-toastify";
import axiosInstance from "Services/AxiosInstane";
import { PoolContext } from "../../Context/PoolContext";
import CircularProgress from "@mui/material/CircularProgress";


const SkeletonLoader = () => (
  <div className="w-[40%] h-[70vh] p-5 rounded-[15px] shadow-[0px_0px_5px_1px_rgba(55,37,221,0.16)]">
    {/* Toggle skeleton */}
    <div className="mb-6">
      <div className="h-6 w-32 bg-gray-200 rounded animate-pulse" />
    </div>

    {/* Form fields skeleton */}
    <div className="space-y-6">
      {/* Server IP field */}
      <div className="h-14 bg-gray-200 rounded animate-pulse" />
      
      {/* Server Port field */}
      <div className="h-14 bg-gray-200 rounded animate-pulse" />
      
      {/* Email field */}
      <div className="h-14 bg-gray-200 rounded animate-pulse" />
      
      {/* User Authentication checkbox */}
      <div className="h-6 w-40 bg-gray-200 rounded animate-pulse" />
      
      {/* Radio buttons */}
      <div className="space-y-2">
        <div className="h-6 w-24 bg-gray-200 rounded animate-pulse" />
        <div className="h-6 w-24 bg-gray-200 rounded animate-pulse" />
      </div>
      
      {/* Footer buttons */}
      <div className="flex justify-between mt-5">
        <div className="h-10 w-24 bg-gray-200 rounded animate-pulse" />
        <div className="h-10 w-24 bg-gray-200 rounded animate-pulse" />
      </div>
    </div>
  </div>
);
export default function SMTP() {
    
    const [data, setData] = useState({
        serverIP : '',
        serverPort:'',
        userName:"",
        password:'',
        email:'',
        connOption:'',
        userAuthentication: "false",
        smtpStatus: false,
        receiverMail:'',
       
    });
    
    const [isEnabled,setIsEnabled]=useState(true);
    const [existingConfig, setExistingConfig] = useState(false);
    const [receiverEmail, setReceiverEmail] = useState('');
    const [openDialog, setOpenDialog] = useState(false);
    const [loading, setLoading] = useState(true);
    const[sendmail,setSendmail] = useState(false);
    const pc = useContext(PoolContext);
    const token=pc.token

    useEffect(()=>{
        if(isEnabled){
            const fetchData=async ()=>{
                setLoading(true);
                try{
                    // let response = await axiosInstance.get(`${process.env.REACT_APP_FRONTEND_URL}/get_smtp`);
                    let response = await axiosInstance.get(
                        `${process.env.REACT_APP_BACKEND_URL}/v1/smtp/smtp-get`,
                        {
                          headers: {
                            Authorization: `Bearer ${token}`  // Add the Authorization header with the token
                          }
                        }
                      );
                  
                    if(response.data && response.data[0]){

                        setData({
                            serverIP: response.data[0].serverIP,
                            serverPort: response.data[0].serverPort,
                            userName: response.data[0].userName,
                            password: response.data[0].password,
                            email: response.data[0].email,
                            connOption: response.data[0].connOption,
                            userAuthentication: response.data[0].userAuthentication,
                            smtpStatus: response.data[0].smtpStatus,
                            receiverMail:response.data[0].receiverMail,
                        });
                        
                        setExistingConfig(true);
                    }else {
                        setExistingConfig(false);
                    }
                }catch(error){
                    console.error('Error fetching SMTP config:', error);
                    toast.error('Failed to fetch SMTP configuration.');
                }finally{
                    setLoading(false);
                }
            };
            fetchData();
        }
    },[isEnabled]);

        // const navigate = useNavigate()

        const handleToggleChange= async (event)=>{
        const check=event.target.checked
        setIsEnabled(check);
        if (!check) {
         
            setData({
                serverIP: '',
                serverPort: '',
                email: '',
                testEmail:'',
                connOption: '',
                userAuthentication: "false",
                userName: '',
                password: '',
                smtpStatus: false,
                receiverMail: '',

            });

            try {
                const updatedData = { ...data, smtpStatus: false};  
                // const response = await axiosInstance.put(`${process.env.REACT_APP_FRONTEND_URL}/update_smtpEnabled`, updatedData);
                const response = await axiosInstance.patch(
                    `${process.env.REACT_APP_BACKEND_URL}/v1/smtp/smtp-update-status`, 
                    updatedData,
                    {
                      headers: {
                        Authorization: `Bearer ${token}`  // Add the Authorization header with the token
                      }
                    }
                  );
                
                
                if (response.status === 200) {
                    toast.success('SMTP config disabled!');
                } 
            } catch (error) {
                console.error('Error disabling SMTP config:', error);
                // toast.error('Failed to update SMTP configuration. Please try again.');
            }
        }else {
    
            try {
                const updatedData = { ...data, smtpStatus: true };
                // const response = await axiosInstance.put(`${process.env.REACT_APP_FRONTEND_URL}/update_smtpEnabled`, updatedData);
                const response = await axiosInstance.patch(
                    `${process.env.REACT_APP_BACKEND_URL}/v1/smtp/smtp-update-status`, 
                    updatedData,
                    {
                      headers: {
                        Authorization: `Bearer ${token}`  // Add the Authorization header with the token
                      }
                    }
                  );
                // console.log(response.data);
    
                if (response.status === 200) {
                    toast.success('SMTP config enabled!');
                } else {
                    toast.error('Failed to enable SMTP config.');
                }
            } catch (error) {
                console.error('Error enabling SMTP config:', error);
                // toast.error('Failed to update SMTP configuration. Please try again.');
            }
        
         }
    };
    
        const handleCheckboxChange = (event) => {
        const isChecked = event.target.checked;
        setData({
            ...data,
            userAuthentication: isChecked ? "true" : "false",
            userName: isChecked ? data.userName : '', 
            password: isChecked ? data.password : '' 
        });
    };
    
    const handleRadioChange = (event) => {
        let value = event.target.value;
        setData({ ...data, connOption: value });
    };

    const handleSubmit = async (e) => {
        // console.log('Data being sent:', data);

        const smtpData ={ ...data, smtpStatus: isEnabled, userAuthentication: data.userAuthentication };
       

        e.preventDefault();
        let response
        let email_valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        try{
            if (isEnabled){
                if (!email_valid.test(data.email)) {
                    toast.error('Please enter a valid email address.');
                    return;
                }
                try{
                    if(existingConfig){
                        // response = await axiosInstance.put(process.env.REACT_APP_FRONTEND_URL + "/update_smtp",smtpData); 
                        const response = await axiosInstance.put(
                            // process.env.REACT_APP_FRONTEND_URL + "/update_smtp", 
                            `${process.env.REACT_APP_BACKEND_URL}/v1/smtp/smtp-update`,
                            smtpData, 
                            {
                              headers: {
                                Authorization: `Bearer ${token}`  // Adding Authorization header with the token
                              }
                            }
                          );
                        toast.success("IP updated successfully")
                       
                    }else{
                        // response = await axiosInstance.post(process.env.REACT_APP_FRONTEND_URL + "/add_smtp",smtpData);
                        const response = await axiosInstance.put(
                            // process.env.REACT_APP_FRONTEND_URL + "/add_smtp", 
                            `${process.env.REACT_APP_BACKEND_URL}/v1/smtp/smtp-post`,
                            smtpData, 
                            {
                              headers: {
                                Authorization: `Bearer ${token}`  // Adding Authorization header with the token
                              }
                            }
                          );
                        console.log('Form submitted:',response.data);
                        toast.success('IP added Successfully');
                    }
                } catch (error) {
                    console.error('Error submitting form:', error);
                    toast.error('Failed to submit the form. Please try again.');
                }
            }
        }
        catch(error){
            toast.error("Something went wrong, please check")
            // console.log("POST URL:", process.env.REACT_APP_FRONTEND_URL + "/add");
            console.error("Error :  ",error);
        }
    };

    const handleTestEmail=async(e) => {
        setOpenDialog(true);
    }
    const closeDialog=async(e) => {
        setOpenDialog(false);
        setReceiverEmail('')
    }
    const sendTestEmail=async(e) => {
        setSendmail(true)
        if(!receiverEmail){
            toast.error("please enter receiver email address")
            return;
        }
        
        const testData= { ...data,receiverMail:receiverEmail};
        
        try{
            // const response = await axiosInstance.post(`${process.env.REACT_APP_FRONTEND_URL}/send_test_mail`, testData);
            const response = await axiosInstance.post(
                `${process.env.REACT_APP_BACKEND_URL}/v1/smtp/smtp-test-mail`, 
                testData, 
                {
                  headers: {
                    Authorization: `Bearer ${token}`  // Adding Authorization header with the token
                  }
                }
              );
           
            if(response.data.message==="Test email sent successfully"){
                toast.success('Test Email sent successfully!');
            }else {
                toast.error('Failed to send test email.');
            }

        }catch (error) {

        console.error("Error sending test email:", error);
        toast.error('Failed to send the test email.');
        }
        finally{
            setSendmail(false)
        }
    }

    return (
        <div className="form-body-smtp">
            <navbar className="navbar">
                <Link className="back-button" to='/'><i class="bi bi-arrow-left-square"></i></Link>
                <h3>SMTP Config</h3>
            </navbar>
            {/* {isEnabled && ( */}
            <div className="toggle">
                <FormGroup >
                    <FormControlLabel
                        control={
                            <Switch     
                                checked={data.smtpStatus}
                                onChange={handleToggleChange}
                                name="enableForm"
                            />
                        }
                        label={data.smtpStatus ? 'Disable SMTP Form' : 'SMTP Config'} 
                    />
                </FormGroup>
            </div>
            <div className="smtp-body" >
                {loading?(  <SkeletonLoader />):(
                <form onSubmit={handleSubmit}>
                    <TextField
                            label="Server IP"
                            variant="outlined"
                            fullWidth
                            margin="normal"
                            name="serverIP"
                            required
                            disabled={!isEnabled}
                            value={data.serverIP}
                            onChange={(e) => setData({...data, serverIP: e.target.value})}
                        />
                        <TextField
                            label="Server Port"
                            variant="outlined"
                            fullWidth
                            margin="normal"
                            name="serverPort"
                            required
                            disabled={!isEnabled}
                            value={data.serverPort}
                            onChange={(e) => setData({...data, serverPort: e.target.value})}
                        />
                        <TextField
                            label="Email "
                            variant="outlined"
                            fullWidth
                            type="email"
                            margin="normal"
                            name = 'email'
                            required
                            disabled={!isEnabled}
                            value={data.email}
                            onChange={(e) => setData({...data, email: e.target.value})}
                        />

                        <FormGroup>
                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={data.userAuthentication === 'true'}
                                        onChange={handleCheckboxChange}
                                        name="userAuthentication"
                                        disabled={!isEnabled}
                                    />
                                }
                                label="User Authentication"
                            />
                        </FormGroup>

                       { data.userAuthentication === "true" && (
                            <div id="auth">
                        
                                    <TextField
                                        label="User Name"
                                        variant="outlined"
                                        fullWidth
                                        margin="normal"
                                        name = "userName"
                                        required
                                        disabled={!isEnabled}
                                        value={data.userName}
                                        onChange={(e) => setData({...data, userName:e.target.value})}
                                    />
                                    <TextField
                                        label="Password"
                                        variant="outlined"
                                        fullWidth
                                        type="password"
                                        margin="normal"
                                        name="password"
                                        required
                                        disabled={!isEnabled}
                                        value={data.password}
                                        onChange={(e) => setData({ ...data, password: e.target.value })}
                                    />
                            </div>
                            )
                        }
                    
                        <RadioGroup
                            aria-label="options"
                            name="controlled-radio-buttons-group"
                            value={data.connOption}
                            onChange = {handleRadioChange}
                            >
                                
                            <FormControlLabel value="SSL" control={<Radio />}  disabled={!isEnabled} label="SSL" />
                            <FormControlLabel value="TLS" control={<Radio />}  disabled={!isEnabled} label="TLS" />

                        </RadioGroup>
                        <div className="footer">
                            <Button className='submit_btn' type="submit" disabled={!isEnabled} variant="contained">Save</Button>
                            <Button className="test-email-btn" onClick={handleTestEmail} disabled={!isEnabled} variant="contained">Test Email</Button>
                        </div>
                    </form>
                    )}
                </div>
            {/* )} */}
            <Dialog open={openDialog} onClose={closeDialog} >
                <DialogTitle>Send Test Email</DialogTitle>
                <DialogContent>
                    <TextField
                        label="Receiver Email"
                        variant="outlined"
                        fullWidth
                        margin="normal"
                        name="receiverEmail"
                        type="email"
                        value={receiverEmail}
                        onChange={(e)=>setReceiverEmail(e.target.value)}
                    />

                </DialogContent>
                <DialogActions>
                    <Button onClick={closeDialog} color="primary">Cancel</Button>
                    <Button 
                onClick={sendTestEmail} 
                color="primary" 
                disabled={sendmail} 
                startIcon={sendmail ? <CircularProgress size={20} /> : null}
            >
                {sendmail ? "Sending..." : "Send"}
            </Button>
                </DialogActions>
            </Dialog>
        </div>
    );
};